sp_widget.client_script:
api.controller = function() {

    var c = this;


    c.processing =
        false;


    c.completeHandover =
        function() {


            if (
                !confirm(
                    'Confirm that the physical item has been verified and handed to the claimant?'
                )
            ) {

                return;

            }


            c.processing =
                true;


            c.server.get({

                action:
                    'completeHandover',

                token:
                    new URLSearchParams(
                        window.location.search
                    ).get('token')

            }).then(
                function(response) {


                    c.processing =
                        false;


                    c.data =
                        response.data;

                }
            );

        };

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH COLLECTION VERIFICATION
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================== */

.cm-collection-page {
  position: relative;
  display: block;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding: 52px 20px 90px;

  background:
    linear-gradient(
      180deg,
      #FBF8EF 0%,
      #F6F8F2 100%
    ) !important;

  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #F6F8F2;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  color: #102E34;

  box-sizing: border-box !important;

  overflow-x: hidden;
}


/* ==========================================================
   GLOBAL BOX SIZING
========================================================== */

.cm-collection-page,
.cm-collection-page *,
.cm-collection-page *::before,
.cm-collection-page *::after {
  box-sizing: border-box;
}


/* ==========================================================
   IMPORTANT: PREVENT SERVICENOW GLOBAL SVG STRETCHING
========================================================== */

.cm-collection-page svg {
  display: block !important;

  max-width: none !important;
  max-height: none !important;

  flex-shrink: 0 !important;
}


/* ==========================================================
   SHELL
========================================================== */

.cm-collection-shell {
  width: 100%;
  max-width: 920px;

  margin: 0 auto;
}


/* ==========================================================
   EYEBROW
========================================================== */

.cm-eyebrow {
  display: inline-flex;

  margin-bottom: 10px;
  padding: 6px 11px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .7px;
}


/* ==========================================================
   ERROR / ACCESS STATE
========================================================== */

.cm-state-card {
  max-width: 620px;

  margin: 55px auto 0;
  padding: 42px 44px;

  text-align: center;

  border: 1px solid #D2DED8;
  border-radius: 24px;

  background: #FFFFFF;

  box-shadow:
    0 14px 36px rgba(16,78,69,.08);
}


.cm-state-icon {
  width: 58px !important;
  height: 58px !important;

  min-width: 58px !important;
  min-height: 58px !important;

  max-width: 58px !important;
  max-height: 58px !important;

  margin: 0 auto 17px;

  display: flex !important;
  align-items: center;
  justify-content: center;

  border-radius: 18px;

  overflow: hidden;
}


.cm-state-icon svg {
  width: 28px !important;
  height: 28px !important;

  min-width: 28px !important;
  min-height: 28px !important;

  max-width: 28px !important;
  max-height: 28px !important;
}


.cm-state-icon-error {
  background: #FBEAE7;
  color: #B5502F;
}


.cm-state-card h1 {
  margin: 2px 0 9px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 28px;
  font-weight: 700;

  letter-spacing: -.5px;
}


.cm-state-card > p {
  max-width: 470px;

  margin: 0 auto;

  color: #506267;

  font-size: 12px;
  line-height: 1.65;
}


.cm-state-note {
  margin-top: 22px;
  padding: 13px 15px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 9px;

  border-radius: 13px;

  background: #F5F8F3;

  color: #506267;

  font-size: 10px;
  line-height: 1.5;
}


.cm-state-note svg {
  width: 18px !important;
  height: 18px !important;

  min-width: 18px !important;
  min-height: 18px !important;

  max-width: 18px !important;
  max-height: 18px !important;

  color: #168C70;
}


.cm-back-btn {
  margin-top: 24px;
  padding: 10px 18px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #D2DED8;
  border-radius: 999px;

  background: #FFFFFF;

  color: #104E45 !important;

  font-size: 10px;
  font-weight: 800;

  text-decoration: none !important;

  transition:
    background .2s ease,
    border-color .2s ease;
}


.cm-back-btn:hover {
  border-color: #15564B;
  background: #EDF5E9;
}


/* ==========================================================
   MAIN CARD
========================================================== */

.cm-collection-card {
  overflow: hidden;

  border: 1px solid #D2DED8;
  border-radius: 26px;

  background: #FFFFFF;

  box-shadow:
    0 14px 38px rgba(16,78,69,.08);
}


/* ==========================================================
   HERO
========================================================== */

.cm-collection-hero {
  padding: 30px;

  display: grid;
  grid-template-columns: auto 1fr auto;

  align-items: center;

  gap: 17px;

  border-bottom: 1px solid #D2DED8;

  background:
    linear-gradient(
      135deg,
      #FBF8EF,
      #F3F8F1
    );
}


.cm-hero-icon {
  width: 54px !important;
  height: 54px !important;

  min-width: 54px !important;
  min-height: 54px !important;

  max-width: 54px !important;
  max-height: 54px !important;

  display: flex !important;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 17px;

  background: #EDF5E9;

  color: #15564B;

  overflow: hidden;
}


.cm-hero-icon svg {
  width: 28px !important;
  height: 28px !important;

  min-width: 28px !important;
  min-height: 28px !important;

  max-width: 28px !important;
  max-height: 28px !important;
}


.cm-hero-copy {
  min-width: 0;
}


.cm-hero-copy .cm-eyebrow {
  margin-bottom: 7px;
}


.cm-hero-copy h1 {
  margin: 0 0 5px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 27px;
  font-weight: 700;

  letter-spacing: -.6px;
}


.cm-hero-copy p {
  max-width: 550px;

  margin: 0;

  color: #506267;

  font-size: 11px;
  line-height: 1.55;
}


.cm-status-chip {
  padding: 7px 12px;

  border-radius: 999px;

  background: #E9F5ED;

  color: #168C70;

  font-size: 9px;
  font-weight: 800;

  white-space: nowrap;
}


.cm-status-chip.completed {
  background: #EDF5E9;
  color: #104E45;
}


/* ==========================================================
   GENERIC SECTION
========================================================== */

.cm-section-heading {
  padding: 26px 30px 14px;
}


.cm-section-heading span {
  display: block;

  margin-bottom: 4px;

  color: #168C70;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: .8px;
}


.cm-section-heading h2 {
  margin: 0;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 18px;
  font-weight: 700;
}


/* ==========================================================
   CLAIM SUMMARY
========================================================== */

.cm-summary-grid {
  padding: 0 30px 5px;

  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));

  gap: 11px;
}


.cm-summary-card {
  min-width: 0;

  padding: 15px;

  border: 1px solid #D2DED8;
  border-radius: 15px;

  background: #F8FAF6;
}


.cm-summary-card span {
  display: block;

  margin-bottom: 6px;

  color: #718185;

  font-size: 8px;
  font-weight: 700;
}


.cm-summary-card strong {
  display: block;

  overflow: hidden;

  color: #104E45;

  font-size: 12px;
  font-weight: 800;

  text-overflow: ellipsis;
}


.cm-summary-card small {
  display: block;

  margin-top: 3px;

  color: #168C70;

  font-size: 9px;
  font-weight: 800;
}


/* ==========================================================
   ITEM COMPARISON
========================================================== */

.cm-items-heading {
  padding-top: 28px;
}


.cm-item-comparison {
  padding: 0 30px 5px;

  display: grid;
  grid-template-columns: 1fr 58px 1fr;

  align-items: center;

  gap: 11px;
}


.cm-item-card {
  min-width: 0;

  padding: 18px;

  border: 1px solid #D2DED8;
  border-radius: 18px;

  background: #FFFFFF;
}


.cm-item-card.lost {
  background:
    linear-gradient(
      145deg,
      #FFFDFC,
      #FDF2EE
    );
}


.cm-item-card.found {
  background:
    linear-gradient(
      145deg,
      #FFFFFF,
      #F2F8EF
    );
}


.cm-item-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 10px;

  margin-bottom: 15px;
}


.cm-item-icon {
  width: 38px !important;
  height: 38px !important;

  min-width: 38px !important;
  min-height: 38px !important;

  max-width: 38px !important;
  max-height: 38px !important;

  display: flex !important;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  overflow: hidden;
}


.cm-item-icon svg {
  width: 20px !important;
  height: 20px !important;

  min-width: 20px !important;
  min-height: 20px !important;

  max-width: 20px !important;
  max-height: 20px !important;
}


.cm-item-icon.lost {
  background: #FBEAE7;
  color: #B5502F;
}


.cm-item-icon.found {
  background: #EDF5E9;
  color: #15564B;
}


.cm-type-pill {
  padding: 5px 8px;

  border-radius: 999px;

  font-size: 8px;
  font-weight: 800;
}


.cm-type-pill.lost {
  background: #FBEAE7;
  color: #B5502F;
}


.cm-type-pill.found {
  background: #EDF5E9;
  color: #15564B;
}


.cm-item-card h3 {
  margin: 0 0 10px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 15px;
  font-weight: 700;
}


.cm-item-meta {
  display: flex;
  flex-wrap: wrap;

  gap: 6px;
}


.cm-item-meta span {
  padding: 5px 8px;

  border-radius: 999px;

  background: rgba(255,255,255,.85);

  color: #506267;

  font-size: 8px;
  font-weight: 700;
}


/* ==========================================================
   MATCH CONNECTOR
========================================================== */

.cm-match-connector {
  display: flex;
  align-items: center;
  justify-content: center;

  flex-direction: column;

  gap: 5px;

  color: #168C70;
}


.cm-match-connector > div {
  width: 34px !important;
  height: 34px !important;

  min-width: 34px !important;
  min-height: 34px !important;

  max-width: 34px !important;
  max-height: 34px !important;

  display: flex !important;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #EDF5E9;

  overflow: hidden;
}


.cm-match-connector svg {
  width: 17px !important;
  height: 17px !important;

  min-width: 17px !important;
  min-height: 17px !important;

  max-width: 17px !important;
  max-height: 17px !important;
}


.cm-match-connector span {
  color: #718185;

  font-size: 7px;
  font-weight: 800;
}


/* ==========================================================
   CUSTODY
========================================================== */

.cm-custody-card {
  margin: 0 30px 8px;
  padding: 16px 17px;

  display: flex;
  align-items: flex-start;

  gap: 12px;

  border-radius: 16px;
}


.cm-custody-card.success {
  border: 1px solid #D7E8DB;

  background: #EDF5E9;

  color: #104E45;
}


.cm-custody-card.warning {
  border: 1px solid #F1DDAA;

  background: #FFF7E6;

  color: #805B16;
}


.cm-custody-icon {
  width: 32px !important;
  height: 32px !important;

  min-width: 32px !important;
  min-height: 32px !important;

  max-width: 32px !important;
  max-height: 32px !important;

  display: flex !important;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 10px;

  background: rgba(255,255,255,.75);

  overflow: hidden;
}


.cm-custody-icon svg {
  width: 17px !important;
  height: 17px !important;

  min-width: 17px !important;
  min-height: 17px !important;

  max-width: 17px !important;
  max-height: 17px !important;
}


.cm-custody-card strong {
  display: block;

  margin-bottom: 3px;

  font-size: 11px;
  font-weight: 800;
}


.cm-custody-card p {
  margin: 0;

  font-size: 9px;
  line-height: 1.5;
}


.cm-custody-meta {
  margin-top: 8px;

  display: flex;
  flex-wrap: wrap;

  gap: 6px 14px;

  color: #506267;

  font-size: 8px;
}


.cm-custody-meta b {
  color: #104E45;
}


/* ==========================================================
   HANDOVER ACTION
========================================================== */

.cm-handover-action {
  margin: 24px 30px 30px;
  padding: 20px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 24px;

  border-radius: 18px;

  background:
    linear-gradient(
      135deg,
      #104E45,
      #15564B
    );

  color: #FFFFFF;
}


.cm-handover-action > div {
  min-width: 0;
}


.cm-handover-action span {
  display: block;

  margin-bottom: 4px;

  color: #CBE8DD;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: .8px;
}


.cm-handover-action h2 {
  margin: 0 0 5px;

  color: #FFFFFF;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 17px;
}


.cm-handover-action p {
  max-width: 520px;

  margin: 0;

  color: #DCEBE6;

  font-size: 9px;
  line-height: 1.5;
}


/* ==========================================================
   COMPLETE PHYSICAL HANDOVER BUTTON
========================================================== */

.cm-complete-handover {
  padding: 11px 17px;

  flex-shrink: 0;

  border: 0;
  border-radius: 999px;

  background: #FFFFFF !important;

  color: #168C70 !important;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  font-size: 9px;
  font-weight: 800;

  cursor: pointer;

  opacity: 1 !important;

  transition:
    transform .2s ease,
    background .2s ease,
    color .2s ease;
}


.cm-complete-handover:hover:not(:disabled) {
  transform: translateY(-1px);

  background: #EDF5E9 !important;

  color: #168C70 !important;
}


.cm-complete-handover:disabled {
  opacity: 1 !important;

  background: #FFFFFF !important;

  color: #168C70 !important;

  cursor: not-allowed;
}


/* ==========================================================
   HANDOVER COMPLETE
========================================================== */

.cm-handover-completed {
  margin: 24px 30px 30px;
  padding: 25px;

  text-align: center;

  border: 1px solid #D2DED8;
  border-radius: 18px;

  background: #EDF5E9;

  color: #104E45;
}


.cm-complete-icon {
  width: 45px !important;
  height: 45px !important;

  min-width: 45px !important;
  min-height: 45px !important;

  max-width: 45px !important;
  max-height: 45px !important;

  margin: 0 auto 11px;

  display: flex !important;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #FFFFFF;

  color: #168C70;

  overflow: hidden;
}


.cm-complete-icon svg {
  width: 22px !important;
  height: 22px !important;

  min-width: 22px !important;
  min-height: 22px !important;

  max-width: 22px !important;
  max-height: 22px !important;
}


.cm-handover-completed > span {
  display: block;

  margin-bottom: 5px;

  color: #168C70;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: .8px;
}


.cm-handover-completed h2 {
  margin: 0 0 5px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 18px;
}


.cm-handover-completed p {
  margin: 0;

  color: #506267;

  font-size: 9px;
}


.cm-complete-meta {
  margin-top: 11px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-wrap: wrap;

  gap: 8px 15px;

  color: #506267;

  font-size: 8px;
}


/* ==========================================================
   SUCCESS MESSAGE
========================================================== */

.cm-success-message {
  margin: -10px 30px 30px;
  padding: 12px 14px;

  display: flex;
  align-items: center;

  gap: 9px;

  border: 1px solid #D7E8DB;
  border-radius: 13px;

  background: #EDF5E9;

  color: #168C70;

  font-size: 9px;
  font-weight: 700;
}


.cm-success-message > div {
  width: 25px !important;
  height: 25px !important;

  min-width: 25px !important;
  min-height: 25px !important;

  max-width: 25px !important;
  max-height: 25px !important;

  display: flex !important;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  background: #FFFFFF;

  overflow: hidden;
}


.cm-success-message svg {
  width: 15px !important;
  height: 15px !important;

  min-width: 15px !important;
  min-height: 15px !important;

  max-width: 15px !important;
  max-height: 15px !important;
}


/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 780px) {

  .cm-collection-page {
    padding:
      42px
      16px
      75px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F6F8F2;
  }


  .cm-summary-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0,1fr)
      );
  }


  .cm-collection-hero {
    grid-template-columns:
      auto 1fr;
  }


  .cm-status-chip {
    grid-column: 1 / -1;

    width: fit-content;

    margin-left: 71px;
  }

}


/* ==========================================================
   MOBILE
========================================================== */

@media (max-width: 600px) {

  .cm-collection-page {
    min-height: 100svh;

    padding:
      32px
      14px
      65px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F6F8F2;
  }


  .cm-state-card {
    margin-top: 25px;

    padding:
      31px
      20px;
  }


  .cm-state-card h1 {
    font-size: 24px;
  }


  .cm-collection-card {
    border-radius: 21px;
  }


  .cm-collection-hero {
    padding: 23px 19px;

    grid-template-columns: 1fr;

    text-align: center;
  }


  .cm-hero-icon {
    margin:
      0 auto;
  }


  .cm-status-chip {
    grid-column: auto;

    width: fit-content;

    margin:
      3px auto 0;
  }


  .cm-hero-copy h1 {
    font-size: 24px;
  }


  .cm-section-heading {
    padding:
      23px
      19px
      13px;
  }


  .cm-summary-grid {
    padding:
      0
      19px
      4px;

    grid-template-columns: 1fr;
  }


  .cm-item-comparison {
    padding:
      0
      19px
      5px;

    grid-template-columns: 1fr;
  }


  .cm-match-connector {
    padding: 4px 0;
  }


  .cm-match-connector > div {
    transform:
      rotate(90deg);
  }


  .cm-custody-card {
    margin:
      0
      19px
      8px;
  }


  .cm-handover-action {
    margin:
      22px
      19px
      23px;

    padding: 19px;

    align-items: stretch;

    flex-direction: column;
  }


  .cm-complete-handover {
    width: 100%;
  }


  .cm-handover-completed {
    margin:
      22px
      19px
      23px;
  }


  .cm-success-message {
    margin:
      -4px
      19px
      23px;
  }

}


/* ==========================================================
   EXTRA SMALL MOBILE
========================================================== */

@media (max-width: 390px) {

  .cm-collection-page {
    padding:
      28px
      10px
      60px;
  }


  .cm-collection-hero {
    padding:
      21px
      15px;
  }


  .cm-section-heading {
    padding:
      21px
      15px
      12px;
  }


  .cm-summary-grid {
    padding:
      0
      15px
      4px;
  }


  .cm-item-comparison {
    padding:
      0
      15px
      5px;
  }


  .cm-custody-card {
    margin:
      0
      15px
      8px;
  }


  .cm-handover-action,
  .cm-handover-completed {
    margin-left: 15px;
    margin-right: 15px;
  }


  .cm-success-message {
    margin-left: 15px;
    margin-right: 15px;
  }

}


/* ==========================================================
   FINAL SERVICENOW OVERRIDE
   PREVENTS GLOBAL SVG / BUTTON RULES FROM BREAKING DESIGN
========================================================== */

.cm-collection-page .cm-hero-icon svg {
  width: 28px !important;
  height: 28px !important;
}


.cm-collection-page .cm-state-icon svg {
  width: 28px !important;
  height: 28px !important;
}


.cm-collection-page .cm-item-icon svg {
  width: 20px !important;
  height: 20px !important;
}


.cm-collection-page .cm-match-connector svg {
  width: 17px !important;
  height: 17px !important;
}


.cm-collection-page .cm-custody-icon svg {
  width: 17px !important;
  height: 17px !important;
}


.cm-collection-page .cm-complete-icon svg {
  width: 22px !important;
  height: 22px !important;
}


.cm-collection-page .cm-success-message svg {
  width: 15px !important;
  height: 15px !important;
}


/* ==========================================================
   FINAL BUTTON COLOR
   WHITE BUTTON + GREEN TEXT
========================================================== */

.cm-collection-page button.cm-complete-handover,
.cm-collection-page button.cm-complete-handover:visited {
  background: #FFFFFF !important;

  color: #168C70 !important;

  -webkit-text-fill-color: #168C70 !important;
}


.cm-collection-page button.cm-complete-handover:hover:not(:disabled),
.cm-collection-page button.cm-complete-handover:focus:not(:disabled),
.cm-collection-page button.cm-complete-handover:active:not(:disabled) {
  background: #EDF5E9 !important;

  color: #168C70 !important;

  -webkit-text-fill-color: #168C70 !important;
}


.cm-collection-page button.cm-complete-handover:disabled {
  background: #FFFFFF !important;

  color: #168C70 !important;

  -webkit-text-fill-color: #168C70 !important;

  opacity: 1 !important;
}

sp_widget.script:
(function() {


    /* =====================================================
       TABLES
    ===================================================== */

    var ITEM_TABLE =
        'x_snc_campusmatch_campusmatch_item';


    var MATCH_TABLE =
        'x_snc_campusmatch_campusmatch_match';


    var CLAIM_TABLE =
        'x_snc_campusmatch_campusmatch_claim';



    /* =====================================================
       DEFAULT OUTPUT
    ===================================================== */

    data.allowed =
        false;


    data.isStaff =
        false;


    data.error =
        '';


    data.success =
        false;


    data.message =
        '';


    data.claim =
        null;



    /* =====================================================
       HELPER
    ===================================================== */

    function normalize(
        value
    ) {

        return (
            value ||
            ''
        )
        .toString()
        .trim()
        .toLowerCase();

    }



    /* =====================================================
       TASK 14 - CAMPUSMATCH STAFF SECURITY
    ===================================================== */

    var access =
        new CampusMatchAccess();


    data.isStaff =
        access.isStaff();


    data.allowed =
        data.isStaff;


    /*
     * IMPORTANT:
     *
     * A valid QR token does NOT authorize handover.
     *
     * The current logged-in user must also have
     * CampusMatch administrative/staff access.
     */

    if (
        !data.allowed
    ) {

        data.error =
            'Security Desk staff access is required.';


        return;

    }



    /* =====================================================
       GET TOKEN
    ===================================================== */

    var token =
        '';


    if (
        input &&
        input.token
    ) {

        token =
            input.token
                .toString()
                .trim();

    }
    else {

        token =
            (
                $sp.getParameter(
                    'token'
                ) ||
                ''
            )
            .toString()
            .trim();

    }



    /* =====================================================
       TOKEN MUST EXIST
    ===================================================== */

    if (
        !token
    ) {

        data.error =
            'Collection QR is missing or invalid.';


        return;

    }



    /* =====================================================
       FIND CLAIM USING COLLECTION TOKEN

       Actual column name:
       collection_toke0
    ===================================================== */

    var claim =
        new GlideRecord(
            CLAIM_TABLE
        );


    claim.addQuery(
        'collection_toke0',
        token
    );


    claim.setLimit(
        1
    );


    claim.query();


    if (
        !claim.next()
    ) {

        /*
         * This also covers withdrawn Claims whose
         * collection token has already been cleared.
         */

        data.error =
            'This collection QR is no longer valid.';


        return;

    }



    /* =====================================================
       CLAIM STATUS VALIDATION
    ===================================================== */

    var claimStatus =
        normalize(
            claim.getValue(
                'claim_status'
            )
        );



    /* -----------------------------------------------------
       WITHDRAWN
    ----------------------------------------------------- */

    if (
        claimStatus ===
            'withdrawn'
    ) {

        data.error =
            'Collection unavailable. This ownership claim has been withdrawn and this item must not be handed over using this collection pass.';


        return;

    }



    /* -----------------------------------------------------
       REJECTED
    ----------------------------------------------------- */

    if (
        claimStatus ===
            'rejected'
    ) {

        data.error =
            'Collection unavailable. This ownership claim has been rejected.';


        return;

    }



    /* -----------------------------------------------------
       CANCELLED
    ----------------------------------------------------- */

    if (
        claimStatus ===
            'cancelled'
    ) {

        data.error =
            'Collection unavailable. This ownership claim has been cancelled.';


        return;

    }



    /* -----------------------------------------------------
       MUST BE APPROVED
    ----------------------------------------------------- */

    if (
        claimStatus !==
            'approved'
    ) {

        data.error =
            'This ownership claim has not been approved for collection.';


        return;

    }



    /* =====================================================
       LOAD MATCH
    ===================================================== */

    var matchId =
        claim.getValue(
            'match'
        );


    if (
        !matchId
    ) {

        data.error =
            'This Claim is not linked to a Match.';


        return;

    }



    var match =
        new GlideRecord(
            MATCH_TABLE
        );


    if (
        !match.get(
            matchId
        )
    ) {

        data.error =
            'The Match linked to this Claim could not be found.';


        return;

    }



    /* =====================================================
       MATCH MUST NOT BE WITHDRAWN
    ===================================================== */

    if (
        match.isValidField(
            'status'
        )
    ) {

        var matchStatus =
            normalize(
                match.getValue(
                    'status'
                )
            );


        if (
            matchStatus ===
                'withdrawn'
        ) {

            data.error =
                'Collection unavailable. The ownership Match linked to this Claim has been withdrawn.';


            return;

        }

    }



    /* =====================================================
       GET LOST + FOUND ITEM IDs
    ===================================================== */

    var lostId =
        match.getValue(
            'lost_item'
        );


    var foundId =
        match.getValue(
            'found_item'
        );


    if (
        !lostId ||
        !foundId
    ) {

        data.error =
            'The Match does not contain both Lost and Found Items.';


        return;

    }



    /* =====================================================
       LOAD LOST ITEM
    ===================================================== */

    var lost =
        new GlideRecord(
            ITEM_TABLE
        );


    if (
        !lost.get(
            lostId
        )
    ) {

        data.error =
            'The Lost Item record could not be loaded.';


        return;

    }



    /* =====================================================
       LOAD FOUND ITEM
    ===================================================== */

    var found =
        new GlideRecord(
            ITEM_TABLE
        );


    if (
        !found.get(
            foundId
        )
    ) {

        data.error =
            'The Found Item record could not be loaded.';


        return;

    }



    /* =====================================================
       CHECK SECURITY DESK CUSTODY
    ===================================================== */

    var atDesk =
        found.getValue(
            'received_at_security_desk'
        ) == '1';



    /* =====================================================
       COMPLETE HANDOVER ACTION
    ===================================================== */

    if (
        input &&
        input.action ===
            'completeHandover'
    ) {


        /* =================================================
           IMPORTANT:
           RELOAD CLAIM AT THE EXACT MOMENT OF HANDOVER

           Example:

           Staff opened page while Claim = Approved.

           Student withdraws Claim in another session.

           Staff then clicks Complete Handover.

           Without reloading, the old page may still hold
           the previously approved Claim object.

           Therefore we reload it NOW.
        ================================================= */

        var freshClaim =
            new GlideRecord(
                CLAIM_TABLE
            );


        if (
            !freshClaim.get(
                claim.getUniqueValue()
            )
        ) {

            data.success =
                false;


            data.message =
                'The Claim could not be revalidated. Handover has been blocked.';

        }
        else {


            /* =============================================
               RECHECK COLLECTION TOKEN
            ============================================= */

            var freshToken =
                (
                    freshClaim.getValue(
                        'collection_toke0'
                    ) ||
                    ''
                )
                .toString()
                .trim();


            if (
                !freshToken ||
                freshToken !== token
            ) {

                data.success =
                    false;


                data.message =
                    'This collection pass is no longer valid. Handover has been blocked.';

            }
            else {


                /* =========================================
                   RECHECK CLAIM STATUS
                ========================================= */

                var freshStatus =
                    normalize(
                        freshClaim.getValue(
                            'claim_status'
                        )
                    );


                if (
                    freshStatus ===
                        'withdrawn'
                ) {

                    data.success =
                        false;


                    data.message =
                        'This claim has been withdrawn. The item must not be handed over.';

                }
                else if (
                    freshStatus ===
                        'rejected'
                ) {

                    data.success =
                        false;


                    data.message =
                        'This claim has been rejected. The item must not be handed over.';

                }
                else if (
                    freshStatus ===
                        'cancelled'
                ) {

                    data.success =
                        false;


                    data.message =
                        'This claim has been cancelled. The item must not be handed over.';

                }
                else if (
                    freshStatus !==
                        'approved'
                ) {

                    data.success =
                        false;


                    data.message =
                        'This claim is no longer approved for collection.';

                }


                /* =========================================
                   ALREADY HANDED OVER
                ========================================= */

                else if (
                    freshClaim.getValue(
                        'handover_completed'
                    ) == '1'
                ) {

                    data.success =
                        false;


                    data.message =
                        'This item has already been handed over.';

                }


                /* =========================================
                   ITEM MUST PHYSICALLY BE AT SECURITY DESK
                ========================================= */

                else if (
                    !atDesk
                ) {

                    data.success =
                        false;


                    data.message =
                        'The physical item is not recorded as being at the Security Desk.';

                }


                /* =========================================
                   RECHECK MATCH STATUS
                ========================================= */

                else {

                    var freshMatch =
                        new GlideRecord(
                            MATCH_TABLE
                        );


                    if (
                        !freshMatch.get(
                            matchId
                        )
                    ) {

                        data.success =
                            false;


                        data.message =
                            'The Match could not be revalidated. Handover has been blocked.';

                    }
                    else {

                        var freshMatchStatus =
                            '';


                        if (
                            freshMatch.isValidField(
                                'status'
                            )
                        ) {

                            freshMatchStatus =
                                normalize(
                                    freshMatch.getValue(
                                        'status'
                                    )
                                );

                        }


                        if (
                            freshMatchStatus ===
                                'withdrawn'
                        ) {

                            data.success =
                                false;


                            data.message =
                                'The ownership Match has been withdrawn. Handover has been blocked.';

                        }


                        /* =================================
                           COMPLETE HANDOVER
                        ================================= */

                        else {

                            freshClaim.setValue(
                                'handover_completed',
                                true
                            );


                            freshClaim.setValue(
                                'handed_over_by',
                                gs.getUserID()
                            );


                            freshClaim.setValue(
                                'handed_over_on',
                                new GlideDateTime()
                            );


                            freshClaim.update();



                            /* =============================
                               RESOLVE LOST ITEM
                            ============================= */

                            lost.setValue(
                                'status',
                                'resolved'
                            );


                            lost.update();



                            /* =============================
                               RESOLVE FOUND ITEM
                            ============================= */

                            found.setValue(
                                'status',
                                'resolved'
                            );


                            found.update();



                            data.success =
                                true;


                            data.message =
                                'Handover completed successfully. CampusMatch has resolved both Item reports.';

                        }

                    }

                }

            }

        }



        /* =================================================
           RELOAD UPDATED RECORDS
        ================================================= */

        claim.get(
            claim.getUniqueValue()
        );


        lost.get(
            lostId
        );


        found.get(
            foundId
        );

    }



    /* =====================================================
       BUILD COLLECTION VERIFICATION VIEW
    ===================================================== */

    data.claim = {

        sys_id:
            claim.getUniqueValue(),


        number:
            claim.getDisplayValue(
                'number'
            ) || '',


        claimant:
            claim.getDisplayValue(
                'claimant'
            ) || '—',


        status:
            claim.getDisplayValue(
                'claim_status'
            ) || '—',


        statusValue:
            normalize(
                claim.getValue(
                    'claim_status'
                )
            ),


        verificationResult:
            claim.getDisplayValue(
                'u_verification_result'
            ) || '—',


        verificationScore:
            claim.getDisplayValue(
                'u_verification_score'
            ) || '0',


        handoverCompleted:
            claim.getValue(
                'handover_completed'
            ) == '1',


        handedOverBy:
            claim.getDisplayValue(
                'handed_over_by'
            ) || '',


        handedOverOn:
            claim.getDisplayValue(
                'handed_over_on'
            ) || '',



        /* =================================================
           LOST ITEM
        ================================================= */

        lost: {

            number:
                lost.getDisplayValue(
                    'number'
                ) || '',


            title:
                lost.getValue(
                    'title'
                ) || 'Lost Item',


            status:
                lost.getDisplayValue(
                    'status'
                ) || '—'

        },



        /* =================================================
           FOUND ITEM
        ================================================= */

        found: {

            number:
                found.getDisplayValue(
                    'number'
                ) || '',


            title:
                found.getValue(
                    'title'
                ) || 'Found Item',


            status:
                found.getDisplayValue(
                    'status'
                ) || '—',


            atDesk:
                found.getValue(
                    'received_at_security_desk'
                ) == '1',


            receivedBy:
                found.getDisplayValue(
                    'received_by'
                ) || '',


            receivedOn:
                found.getDisplayValue(
                    'received_on'
                ) || ''

        }

    };


})();
